		Images: Images{Execution: "sha256:" + strings.Repeat("b", 64), Verification: "sha256:" + strings.Repeat("c", 64)}}
}

func TestPolicyCanonicalDigestIsStable(t *testing.T) {
	value := validPolicy()
	body, digest, err := value.Canonical()
